                <button
                  onClick={() => {
                    setResourcesOpen(!resourcesOpen)
                    setProductsOpen(false)
                  }}
                  className={`flex items-center gap-1 px-3 py-2 text-sm font-medium rounded-md transition-colors ${
                    resourcesOpen ? 'text-accent bg-accent-light' : 'text-text-secondary hover:text-text-primary hover:bg-surface-muted'
                  }`}
                >
                  Resources
                  <ChevronDown className={`w-4 h-4 transition-transform ${resourcesOpen ? 'rotate-180' : ''}`} />
                </button>

                {resourcesOpen && (
                  <div className="absolute top-full left-0 mt-2 w-[480px] bg-white rounded-xl shadow-2xl border border-border p-6 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="grid grid-cols-3 gap-6">
                      {Object.entries(resourcesMenu).map(([category, items]) => (
                        <div key={category}>
                          <h4 className="text-xs font-semibold text-text-tertiary uppercase tracking-wider mb-3">
                            {category}
                          </h4>
                          <ul className="space-y-2">
                            {items.map((item) => (
                              <li key={item}>
                                <a
                                  href="#"
                                  className="text-sm font-medium text-text-primary hover:text-accent transition-colors"
                                >
                                  {item}
                                </a>
                              </li>
                            ))}
                          </ul>
                        </div>
