          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 text-xs font-semibold bg-accent-light text-accent rounded-full">
            <TrendingUp className="w-3 h-3" />
            Featured
          </span>
          <span className="text-sm text-text-tertiary">{post.date}</span>
        </div>

        {/* Title */}
        <h3
          className={`font-display font-bold text-text-primary leading-tight mb-3 group-hover:text-accent transition-colors ${
            isMain ? 'text-2xl lg:text-3xl' : 'text-lg lg:text-xl'
          }`}
        >
          {post.title}
        </h3>

        {/* Excerpt */}
        <p
          className={`text-text-secondary leading-relaxed mb-6 flex-grow ${
            isMain ? 'text-base lg:text-lg lg:leading-relaxed' : 'text-sm'
          }`}
        >
          {post.excerpt}
        </p>

        {/* Author */}
        <div className="flex items-center justify-between mt-auto pt-4 border-t border-border-light">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-full bg-navy-800 flex items-center justify-center text-white text-xs font-semibold">
              {post.authorInitials}
            </div>
            <span className="text-sm font-medium text-text-primary">{post.author}</span>
          </div>
          <span className="flex items-center gap-1 text-sm font-medium text-accent opacity-0 group-hover:opacity-100 transition-opacity">
            Read <ArrowRight className="w-4 h-4" />
          </span>
        </div>
      </div>

      {/* Stats overlay for main card */}
      {isMain && (
        <div className="hidden lg:block px-10 pb-8">
          <div className="grid grid-cols-4 gap-4 p-4 bg-surface-warm rounded-xl border border-border-light">
            {agenticStats.map((stat) => (
              <div key={stat.label} className="text-center">
                <div className="font-display font-bold text-xl text-accent">{stat.value}</div>
                <div className="text-xs text-text-tertiary mt-1 leading-tight">{stat.label}</div>
              </div>
            ))}
          </div>
        </div>
      )}
    </article>
  )
}

