        {/* Featured Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {featuredPosts.map((post, index) => (
            <FeaturedCard key={post.id} post={post} index={index} />
          ))}
        </div>
      </div>
