}

import { ArrowRight, Loader2 } from 'lucide-react'
import type { Post } from '../data/posts'

interface LatestNewsProps {
  posts: Post[]
  hasMore: boolean
  onShowMore: () => void
  totalCount: number
  searchQuery: string
}

function PostCard({ post }: { post: Post }) {
  const categoryColors: Record<string, string> = {
    General: 'bg-navy-100 text-navy-700',
    Engineering: 'bg-orange-50 text-orange-700',
    Community: 'bg-emerald-50 text-emerald-700',
    'Company News': 'bg-violet-50 text-violet-700',
    Customers: 'bg-sky-50 text-sky-700',
    v0: 'bg-pink-50 text-pink-700',
    Security: 'bg-red-50 text-red-700',
    Changelog: 'bg-amber-50 text-amber-700',
    Press: 'bg-teal-50 text-teal-700',
  }

  return (
    <article className="group bg-white rounded-xl border border-border overflow-hidden transition-all duration-300 hover:shadow-lg hover:shadow-navy-950/5 hover:-translate-y-0.5">
      <div className="p-5 lg:p-6 flex flex-col h-full">
        {/* Category & Date */}
        <div className="flex items-center gap-3 mb-3">
          <span
            className={`inline-block px-2.5 py-1 text-xs font-semibold rounded-full ${
              categoryColors[post.category] || 'bg-surface-muted text-text-secondary'
            }`}
          >
            {post.category}
          </span>
          <span className="text-xs text-text-tertiary">{post.date}</span>
        </div>

        {/* Title */}
        <h3 className="font-display font-bold text-lg text-text-primary leading-snug mb-2 group-hover:text-accent transition-colors">
          {post.title}
        </h3>

        {/* Excerpt */}
        <p className="text-sm text-text-secondary leading-relaxed mb-4 flex-grow line-clamp-3">
          {post.excerpt}
        </p>

        {/* Author */}
        <div className="flex items-center justify-between pt-4 border-t border-border-light">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-full bg-navy-800 flex items-center justify-center text-white text-[10px] font-semibold">
              {post.authorInitials}
            </div>
            <span className="text-sm font-medium text-text-primary">{post.author}</span>
          </div>
          <ArrowRight className="w-4 h-4 text-text-tertiary opacity-0 group-hover:opacity-100 group-hover:text-accent transition-all" />
        </div>
      </div>
    </article>
  )
}

export default function LatestNews({ posts, hasMore, onShowMore, totalCount, searchQuery }: LatestNewsProps) {
  return (
    <section className="bg-surface-warm">
      <div className="max-w-[1280px] mx-auto px-4 sm:px-6 lg:px-8 py-12 lg:py-16">
        {/* Section Header */}
        <div className="flex items-center justify-between mb-8">
          <div>
            <h2 className="font-display font-bold text-2xl lg:text-3xl text-text-primary">
              Latest News
            </h2>
            <p className="mt-2 text-text-secondary">
              {searchQuery
                ? `${totalCount} result${totalCount !== 1 ? 's' : ''} for "${searchQuery}"`
                : 'Fresh from the DeployCloud team'}
            </p>
          </div>
        </div>

        {/* Posts Grid */}
        {posts.length > 0 ? (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {posts.map((post) => (
                <PostCard key={post.id} post={post} />
              ))}
            </div>

            {/* Show More */}
            {hasMore && (
              <div className="flex justify-center mt-10">
                <button
                  onClick={onShowMore}
                  className="inline-flex items-center gap-2 px-6 py-3 text-sm font-semibold text-text-primary bg-white border border-border rounded-lg hover:bg-surface-muted hover:border-navy-300 transition-all duration-200 shadow-sm"
                >
                  Show more posts
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            )}
          </>
        ) : (
          /* No Results */
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="w-16 h-16 bg-surface-muted rounded-full flex items-center justify-center mb-4">
              <Loader2 className="w-8 h-8 text-text-tertiary" />
            </div>
            <h3 className="font-display font-bold text-lg text-text-primary mb-2">
              No results found at this time
            </h3>
            <p className="text-sm text-text-secondary max-w-sm">
              Try again with a different keyword or browse by category.
            </p>
          </div>
        )}
      </div>
    </section>
  )
}

